const express = require('express');
const { TenantAuthorizationService } = require('../services/tenantAuth');

const app = express();
app.use(express.json());

app.post('/api/okta/hooks/token-inline', async (req, res) => {
  const hookApiKey = req.headers['x-okta-hook-key'];
  if (hookApiKey !== process.env.OKTA_INLINE_HOOK_SECRET) {
    return res.status(401).json({ error: 'Unauthorized Okta inline hook' });
  }

  const { data } = req.body;
  const userId = data?.context?.user?.id;
  const requestedTenantId = data?.context?.request?.params?.requestedTenantId;

  // Validate that the user actually belongs to and holds admin privileges in requestedTenantId
  const verifiedRoles = await TenantAuthorizationService.getUserRolesInTenant(userId, requestedTenantId);
  if (!verifiedRoles || verifiedRoles.length === 0) {
    return res.status(403).json({ error: 'Access denied: user has no roles in requested tenant' });
  }

  const responseCommands = [
    {
      type: 'com.okta.access.patch',
      value: [
        {
          op: 'add',
          path: '/claims/tenant_id',
          value: requestedTenantId
        },
        {
          op: 'add',
          path: '/claims/roles',
          value: verifiedRoles
        }
      ]
    }
  ];

  res.json({ commands: responseCommands });
});

app.listen(9004);
